            // -------- Vote: F6 mismatch precedes freshness + crypto ----------
            #[test]
            fn d7a_vote_f6_mismatch_precedes_freshness() {
                let fixture = make_fixture(4);
                let pv = make_ctx(&fixture, None);
                let current = snapshot_unavailable(&pv, CurrentStateUnavailableReason::MissingStorage);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();

                let v = signed_vote(0, &fixture); // validator_index 0 vs origin 1
                deliver_vote_fresh(
                    &mut engine,
                    &mut stats,
                    None,
                    Some(&pv),
                    Some(&current),
                    &v,
                    &metrics,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                assert_eq!(stats.inbound_sender_binding_rejected_total, 1);
                assert_eq!(stats.inbound_vote_current_state_unavailable_total, 0);
                assert_eq!(stats.inbound_vote_authority_superseded_total, 0);
                assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
            }

            // =============================================================
            // Run 422 D7-A1 — MISSING-OWNER rejection: a present
            // `ProposalVoteAuthority` with NO current-authorization owner
            // (`current_auth == None`) under `Required` is a
            // current-state-unavailable rejection, distinct from an owner
            // whose current state is present-but-unavailable. It must reject
            // BEFORE cryptographic verification and any downstream effect.
            // =============================================================

            // -------- Proposal: present authority + current_auth=None ⇒
            // fail-closed BEFORE crypto, distinct from unavailable owner. -----
            #[test]
            fn d7a1_proposal_missing_owner_rejects_before_crypto() {
                let fixture = make_fixture(4);
                // Wrap the REAL backend so we can DIRECTLY count signature
                // verifications (not merely infer from the latency counter).
                let backend_calls = Arc::new(AtomicU64::new(0));
                let pv = counting_pv(&fixture, &backend_calls);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let view_before = engine.current_view();
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);
                // Recording outbound facade: assert zero outbound actions.
                let facade = D7ActionRecorder::default();

                let p = signed_proposal(1, &fixture);
                // Establish SEPARATELY that this signature is valid under the
                // exact D6 domain the handler uses, so the handler rejection is
                // attributable ONLY to the missing current authorization and not
                // to an invalid signature.
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p,
                        ValidatorId(1),
                        fixture.validators.as_ref(),
                        fixture.kp.as_ref(),
                        fixture.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_ok(),
                    "control: the test proposal signature is valid"
                );

                // Isolate the direct backend-call counter: the standalone
                // control verification above went through the fixture's own
                // registry (not `pv`'s counting registry), so reset to zero
                // before the handler call and assert the handler makes zero.
                backend_calls.store(0, SeqCst);

                let detector = deliver_proposal_fresh(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    None,
                    Some(&pv),  // authority IS present
                    None,       // but NO current-authorization owner is wired
                    &p,
                    &metrics,
                    Some(&facade),
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                // F6 admission occurred (the missing-owner decision is reached
                // only AFTER sender binding).
                assert_eq!(gate.metrics().accepted(), 1, "F6 admitted first");
                // The current-state-unavailable counter increases exactly once
                // (same counter as an unavailable owner; missing owner is not a
                // superseded case).
                assert_eq!(stats.inbound_proposal_current_state_unavailable_total, 1);
                assert_eq!(stats.inbound_proposal_authority_superseded_total, 0);
                assert_eq!(stats.inbound_proposal_authority_stale_before_effect_total, 0);
                // The REAL signature backend was NEVER invoked: a direct
                // backend-call counter of zero (the latency-observation counter
                // is only supplementary evidence, not a backend-call counter).
                assert_eq!(
                    backend_calls.load(SeqCst),
                    0,
                    "missing owner: real signature backend must not be called"
                );
                assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
                assert_eq!(stats.inbound_proposal_verify_accepted, 0);
                assert_eq!(stats.inbound_proposal_verify_rejected_total, 0);
                // No delivery, engine ingestion, reconfig observation, view
                // mutation, restore deferral, or outbound action.
                assert_eq!(stats.inbound_proposals_delivered, 0);
                assert_eq!(stats.inbound_proposals_engine_accepted, 0);
                assert_eq!(stats.restore_catchup_proposals_deferred, 0);
                assert_eq!(facade.total(), 0, "no outbound actions on rejection");
                assert!(detector.header_cache.is_empty());
                assert_eq!(engine.current_view(), view_before);
            }

            // -------- Proposal POSITIVE control: a coherently bound snapshot
            // DOES invoke the real signature backend (direct instrumentation
            // proof). ---------------------------------------------------------
            #[test]
            fn d7a1_proposal_backend_call_counter_positive_control() {
                let fixture = make_fixture(4);
                let backend_calls = Arc::new(AtomicU64::new(0));
                let pv = counting_pv(&fixture, &backend_calls);
                let current = snapshot_matching(&pv);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);

                let p = signed_proposal(1, &fixture);
                deliver_proposal_fresh(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    None,
                    Some(&pv),
                    Some(&current),
                    &p,
                    &metrics,
                    None,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                // The real backend WAS invoked (proves the counter is wired to
                // the actual verify path), and verification succeeded.
                assert!(
                    backend_calls.load(SeqCst) >= 1,
                    "positive control: real signature backend must be called"
                );
                assert_eq!(stats.inbound_proposal_verify_accepted, 1);
                assert!(stats.proposal_vote_crypto_verify_latency_observations_total >= 1);
            }



            // -------- Proposal: F6 mismatch STILL precedes the missing-owner
            // decision (sender binding rejects first). -----------------------
            #[test]
            fn d7a1_proposal_f6_mismatch_precedes_missing_owner() {
                let fixture = make_fixture(4);
                let pv = make_ctx(&fixture, None);
                let gate = pv_binding_gate(4);
                // Authenticated as validator 1 but the proposal claims proposer 0.
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);

                let p = signed_proposal(0, &fixture); // claimed proposer 0
                deliver_proposal_fresh(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    None,
                    Some(&pv),
                    None, // missing owner would reject IF reached
                    &p,
                    &metrics,
                    None,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                assert_eq!(stats.inbound_sender_binding_rejected_total, 1);
                assert_eq!(gate.metrics().accepted(), 0);
                // The missing-owner decision was never reached (F6 rejected
                // first): no current-state-unavailable count, no crypto.
                assert_eq!(stats.inbound_proposal_current_state_unavailable_total, 0);
                assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
            }

            // -------- Vote: present authority + current_auth=None ⇒
            // fail-closed BEFORE crypto, distinct from unavailable owner. -----
            #[test]
            fn d7a1_vote_missing_owner_rejects_before_crypto() {
                use qbind_wire::io::WireEncode;
                let fixture = make_fixture(4);
                let backend_calls = Arc::new(AtomicU64::new(0));
                let pv = counting_pv(&fixture, &backend_calls);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let view_before = engine.current_view();
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let facade = D7ActionRecorder::default();

                let v = signed_vote(1, &fixture);
                // Establish SEPARATELY that this signature is valid under the
                // exact D6 domain, so the rejection is attributable only to the
                // missing current authorization.
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &v,
                        ValidatorId(1),
                        fixture.validators.as_ref(),
                        fixture.kp.as_ref(),
                        fixture.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_ok(),
                    "control: the test vote signature is valid"
                );

                // Isolate the direct backend-call counter before the handler
                // call (the control verification above used the fixture's own
                // registry, not `pv`'s counting registry).
                backend_calls.store(0, SeqCst);

                let mut bytes = Vec::new();
                v.encode(&mut bytes);
                let mut restore = RestoreCatchupModeState::from_config(None);
                handle_inbound_consensus_msg(
                    &mut engine,
                    ConsensusNetMsg::Vote(bytes),
                    &mut stats,
                    Some(&facade), // recording outbound facade
                    &metrics,
                    ValidatorId(0),
                    &mut restore,
                    None,
                    Some(&pv), // authority IS present
                    None,      // but NO current-authorization owner is wired
                    &mut BinaryReconfigDetector::default(),
                    Some(&origin),
                    Some(&gate),
                    None, // Run 422 D7-D10: signing-reservation journal (unwired here)
                    ConsensusVerificationPolicy::Required,
                );

                assert_eq!(gate.metrics().accepted(), 1, "F6 admitted first");
                assert_eq!(stats.inbound_vote_current_state_unavailable_total, 1);
                assert_eq!(stats.inbound_vote_authority_superseded_total, 0);
                assert_eq!(stats.inbound_vote_authority_stale_before_effect_total, 0);
                // The REAL signature backend was NEVER invoked.
                assert_eq!(
                    backend_calls.load(SeqCst),
                    0,
                    "missing owner: real signature backend must not be called"
                );
                assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
                assert_eq!(stats.inbound_vote_verify_accepted, 0);
                assert_eq!(stats.inbound_vote_verify_rejected_total, 0);
                assert_eq!(stats.inbound_votes_delivered, 0);
                assert_eq!(stats.inbound_votes_engine_accepted, 0);
                assert_eq!(facade.total(), 0, "no outbound actions on rejection");
                assert_eq!(engine.current_view(), view_before);
            }

            // -------- Vote POSITIVE control: a coherently bound snapshot DOES
            // invoke the real signature backend. -----------------------------
            #[test]
            fn d7a1_vote_backend_call_counter_positive_control() {
                let fixture = make_fixture(4);
                let backend_calls = Arc::new(AtomicU64::new(0));
                let pv = counting_pv(&fixture, &backend_calls);
                let current = snapshot_matching(&pv);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();

                let v = signed_vote(1, &fixture);
                deliver_vote_fresh(
                    &mut engine,
                    &mut stats,
                    None,
                    Some(&pv),
                    Some(&current),
                    &v,
                    &metrics,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                assert!(
                    backend_calls.load(SeqCst) >= 1,
                    "positive control: real signature backend must be called"
                );
                assert_eq!(stats.inbound_vote_verify_accepted, 1);
                assert!(stats.proposal_vote_crypto_verify_latency_observations_total >= 1);
            }

            // -------- Vote: F6 mismatch STILL precedes the missing-owner
            // decision (sender binding rejects first). -----------------------
            #[test]
            fn d7a1_vote_f6_mismatch_precedes_missing_owner() {
                let fixture = make_fixture(4);
                let pv = make_ctx(&fixture, None);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();

                let v = signed_vote(0, &fixture); // validator_index 0 vs origin 1
                deliver_vote_fresh(
                    &mut engine,
                    &mut stats,
                    None,
                    Some(&pv),
                    None, // missing owner would reject IF reached
                    &v,
                    &metrics,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                assert_eq!(stats.inbound_sender_binding_rejected_total, 1);
                assert_eq!(gate.metrics().accepted(), 0);
                assert_eq!(stats.inbound_vote_current_state_unavailable_total, 0);
                assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
            }

            // authorization; neither can a present current-authorization owner
            // on its own. With `pv_authority == None` the frame is rejected
            // authority-unavailable regardless of an established current state.
            #[test]
            fn d7a_timeout_context_cannot_supply_pv_authorization() {
                let fixture = make_fixture(4);
                let timeout_ctx = make_timeout_ctx(&fixture, Some(ValidatorId(0)));
                assert!(timeout_ctx.signer.is_some(), "valid legacy Timeout signer");
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(0), ValidatorId(0));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);

                let p = signed_proposal(0, &fixture);
                deliver_proposal_fresh(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    Some(&timeout_ctx),
                    None, // NO Proposal/Vote authority
                    None, // and NO current-authorization snapshot
                    &p,
                    &metrics,
                    None,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                // Rejected authority-unavailable: the Timeout context does NOT
                // substitute for a Proposal/Vote authorization snapshot. A
                // current-authorization snapshot is inseparable from its bound
                // verifier (Run 422 D7-A2), so a Timeout context can never leak
                // into the Proposal/Vote crypto path.
                assert_eq!(stats.inbound_proposal_verification_context_unavailable_total, 1);
                assert_eq!(stats.inbound_proposal_current_state_unavailable_total, 0);
                assert_eq!(stats.inbound_proposal_authority_superseded_total, 0);
                assert_eq!(stats.inbound_proposals_delivered, 0);
            }

            // -------- Deterministic replacement interleaving: a successful
            // check cannot be reused across an in-process invalidation before
            // its effect. Uses explicit state-machine scheduling (admit →
            // replace → confirm), no sleeps. -------------------------------
            #[test]
            fn d7a_ticket_confirm_fails_after_replacement() {
                let mut owner = owner_matching_a();
                assert_eq!(owner.generation(), 0);

                // Admit: freshness passes against the matching current state.
                let ticket = owner.admit().expect("admit succeeds against matching state");
                assert_eq!(ticket.generation(), 0);
                // Confirm before any replacement: still valid.
                assert!(owner.confirm(&ticket).is_ok());

                // Deterministic in-flight replacement: current state moves to B.
                owner.replace_for_fixture(LocalAuthorizationState::Established(
                    ObservedConsensusConfiguration::new(
                        D7A_CHAIN,
                        d7a_genesis_hash(),
                        COMMIT_B,
                        4,
                        1,
                    ),
                ));
                assert_eq!(owner.generation(), 1);

                // The earlier admitted ticket must NOT be reusable across the
                // invalidation: confirm fails closed (generation advanced).
                let err = owner.confirm(&ticket).expect_err("stale ticket rejected");
                match err {
                    ConfirmError::Stale(inner) => {
                        assert_eq!(inner.admitted_generation, 0);
                        assert_eq!(inner.current_generation, 1);
                    }
                    other => panic!("expected Stale confirm rejection, got {other:?}"),
                }

                // A fresh admit now fails Superseded (candidate A is stale vs B).
                match owner.admit() {
                    Err(FreshnessError::Superseded(_)) => {}
                    other => panic!("expected Superseded after replacement, got {other:?}"),
                }
            }

            // -------- ACTIVE restore-mode: negative (unavailable current state
            // rejects BEFORE restore deferral) + admitted positive control
            // (matching state admits, then the valid op is deferred). --------
            #[test]
            fn d7a_active_restore_mode_negative_and_positive_control() {
                let fixture = make_fixture(4);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(0), ValidatorId(0));
                let metrics = make_metrics();
                // Height 7 > committed(5)+1 ⇒ defers if admitted.
                let proposal = signed_proposal_at_height(0, 7, [0xAB; 32], &fixture);

                // Positive control: matching current state admits freshness AND
                // crypto, then active restore mode defers the valid proposal.
                {
                    let pv = make_ctx(&fixture, None);
                    let current = snapshot_matching(&pv);
                    let mut engine = make_engine(ValidatorId(0), 4);
                    engine.initialize_from_snapshot_baseline([0x01; 32], 5);
                    let mut restore = RestoreCatchupModeState::from_config(Some(RestoreBaseline {
                        snapshot_height: 5,
                        snapshot_block_id: [0x01; 32],
                    }));
                    assert!(restore.is_active());
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let facade = CountingFacade::default();

                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv),
                        Some(&current),
                        &proposal,
                        &metrics,
                        Some(&facade),
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );

                    assert_eq!(stats.inbound_proposal_verify_accepted, 1, "control verified");
                    assert_eq!(
                        stats.restore_catchup_proposals_deferred, 1,
                        "control: valid proposal deferred by active restore mode"
                    );
                    assert_eq!(stats.inbound_proposal_current_state_unavailable_total, 0);
                    assert_eq!(stats.inbound_proposals_delivered, 0);
                    assert_eq!(facade.calls.load(SeqCst), 0);
                    assert!(restore.is_active());
                }

                // Negative: unavailable current state rejects BEFORE the
                // restore-deferral branch (no deferral recorded).
                {
                    let pv = make_ctx(&fixture, None);
                    let current = snapshot_unavailable(&pv, CurrentStateUnavailableReason::MissingStorage);
                    let mut engine = make_engine(ValidatorId(0), 4);
                    engine.initialize_from_snapshot_baseline([0x01; 32], 5);
                    let mut restore = RestoreCatchupModeState::from_config(Some(RestoreBaseline {
                        snapshot_height: 5,
                        snapshot_block_id: [0x01; 32],
                    }));
                    assert!(restore.is_active());
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let facade = CountingFacade::default();

                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv),
                        Some(&current),
                        &proposal,
                        &metrics,
                        Some(&facade),
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );

                    assert_eq!(stats.inbound_proposal_current_state_unavailable_total, 1);
                    assert_eq!(
                        stats.restore_catchup_proposals_deferred, 0,
                        "negative: no deferral — rejected before restore branch"
                    );
                    assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
                    assert_eq!(stats.inbound_proposals_delivered, 0);
                    assert_eq!(facade.calls.load(SeqCst), 0);
                    assert!(restore.is_active());
                }
            }

            // ================================================================
            // Run 422 D7-A2 (finding #2) — SNAPSHOT-BINDING behavioral proof.
            //
            // An owner authorizing identity A must not admit verification
            // performed under an unrelated verifier B. The snapshot binds the
            // admitted owner to the exact verifier the handler consumes, so a
            // separately-supplied context cannot substitute different inputs.
            // ================================================================

            /// Alternate signing domain B: different genesis identity, authority
            /// commitment, and runtime chain identity from the `d5_control_domain`.
            /// A trusted, test-identified fixture domain (not production data).
            fn alt_domain_b() -> ProposalVoteSigningDomainV2 {
                ProposalVoteSigningDomainV2::try_new(
                    ChainId(0xB0B0_0000_0000_0002),
                    0, // expected wire chain id (matches base_header chain_id 0)
                    [0x7Bu8; 32],
                    [0x8Bu8; 32],
                )
                .expect("valid alt domain B")
            }

            /// Owner authorizing the identity of verifier `pv` (coherent).
            fn owner_authorizing(pv: &ProposalVoteAuthority) -> CurrentAuthorizationOwner {
                let cand = coherent_authority_for(pv);
                let observed = cand.config_identity();
                CurrentAuthorizationOwner::establish_for_fixture(cand, observed)
            }

            // -------- Owner A paired with verifier B ⇒ cannot bind; and B is
            // independently a VALID verifier when coherently bound. -----------
            #[test]
            fn d7a2_bind_rejects_owner_a_verifier_b_while_b_is_valid() {
                let fa = make_fixture(4);
                let fb = make_fixture(4);
                let domain_b = alt_domain_b();
                let pv_a = make_ctx(&fa, None); // d5 control domain
                let pv_b = make_ctx_v2(&fb, None, domain_b.clone());

                // Owner authorizes identity A; binding it to verifier B fails
                // closed (B's genesis / commitment / chain identity differ).
                let err = AuthorizedProposalVoteSnapshot::try_bind(
                    owner_authorizing(&pv_a),
                    Arc::new(pv_b.clone()),
                )
                .expect_err("owner for A must not admit verification under B");
                assert!(matches!(
                    err,
                    SnapshotCoherenceError::GenesisIdentityMismatch
                        | SnapshotCoherenceError::AuthorityCommitmentMismatch
                        | SnapshotCoherenceError::ChainIdentityMismatch
                ));

                // Control: B IS a valid verifier when coherently bound — a
                // B-signed proposal verifies through the actual handler. This
                // makes the rejection above attributable to BINDING, not to B
                // being an invalid verifier.
                let current_b = coherent_snapshot_for(&pv_b);
                let p_b = signed_proposal_v2(1, &fb, &domain_b);
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p_b,
                        ValidatorId(1),
                        fb.validators.as_ref(),
                        fb.kp.as_ref(),
                        fb.br.as_ref(),
                        &domain_b,
                    )
                    .is_ok(),
                    "control: the B-signed proposal is valid under B"
                );
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);
                deliver_proposal_fresh(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    None,
                    Some(&pv_b),
                    Some(&current_b),
                    &p_b,
                    &metrics,
                    None,
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );
                assert_eq!(stats.inbound_proposal_verify_accepted, 1, "B verifies when bound to B");
            }

            // -------- Same validator COUNT but different keys ⇒ cannot bind.
            // A count match (or shared membership alone) is insufficient: the
            // ACTUAL key provider must correspond. --------------------------
            #[test]
            fn d7a2_bind_rejects_same_count_different_keys() {
                let fa = make_fixture(4);
                let fb = make_fixture(4); // same count, DIFFERENT keys
                let pv_a = make_ctx(&fa, None);
                let pv_b = make_ctx(&fb, None); // same d5 domain (genesis/commitment/chain equal)

                // (a) Different membership instance: owner over A bound to B.
                // Structural membership (ids + weights) is identical, yet the
                // ACTUAL shared membership differs ⇒ MembershipMismatch.
                let err_membership = AuthorizedProposalVoteSnapshot::try_bind(
                    owner_authorizing(&pv_a),
                    Arc::new(pv_b.clone()),
                )
                .expect_err("same count is not sufficient");
                assert_eq!(err_membership, SnapshotCoherenceError::MembershipMismatch);

                // (b) Isolate the key provider: SHARE B's exact membership but
                // pair A's key provider ⇒ membership passes, KeyProviderNotShared.
                let candidate = Arc::new(
                    crate::genesis_consensus_authority::GenesisConsensusAuthority::for_verification_snapshot_fixture(
                        snapshot_chain_identity_label(pv_b.signing_domain.runtime_chain_id()),
                        *pv_b.signing_domain.genesis_identity(),
                        *pv_b.signing_domain.authority_commitment(),
                        pv_b.signing_domain.expected_wire_chain_id(),
                        pv_b.validators.clone(),   // SHARE B's membership (ptr_eq holds)
                        pv_a.key_provider.clone(), // but A's key provider (ptr_eq fails)
                    ),
                );
                let observed = candidate.config_identity();
                let owner = CurrentAuthorizationOwner::establish_for_fixture(candidate, observed);
                let err_keys =
                    AuthorizedProposalVoteSnapshot::try_bind(owner, Arc::new(pv_b.clone()))
                        .expect_err("shared membership alone is not proof; keys must correspond");
                assert_eq!(err_keys, SnapshotCoherenceError::KeyProviderNotShared);
            }

            // -------- Different genesis / commitment / chain identity ⇒ cannot
            // bind (each isolated field rejects with its specific reason). ----
            #[test]
            fn d7a2_bind_rejects_isolated_genesis_commitment_chain() {
                let f = make_fixture(4);
                let pv = make_ctx(&f, None);
                let dom = &pv.signing_domain;

                // Helper: candidate sharing pv's real membership + key provider,
                // differing in exactly one identity field.
                let build = |chain: String, genesis: [u8; 32], commitment: [u8; 32]| {
                    Arc::new(
                        crate::genesis_consensus_authority::GenesisConsensusAuthority::for_verification_snapshot_fixture(
                            chain,
                            genesis,
                            commitment,
                            dom.expected_wire_chain_id(),
                            pv.validators.clone(),
                            pv.key_provider.clone(),
                        ),
                    )
                };
                let good_chain = snapshot_chain_identity_label(dom.runtime_chain_id());
                let good_genesis = *dom.genesis_identity();
                let good_commit = *dom.authority_commitment();

                // Wrong genesis only.
                let owner = CurrentAuthorizationOwner::establish_for_fixture(
                    build(good_chain.clone(), [0x00u8; 32], good_commit),
                    ObservedConsensusConfiguration::new(good_chain.clone(), [0x00u8; 32], good_commit, 4, 0),
                );
                assert_eq!(
                    AuthorizedProposalVoteSnapshot::try_bind(owner, Arc::new(pv.clone()))
                        .expect_err("genesis mismatch"),
                    SnapshotCoherenceError::GenesisIdentityMismatch
                );

                // Wrong commitment only.
                let owner = CurrentAuthorizationOwner::establish_for_fixture(
                    build(good_chain.clone(), good_genesis, [0x01u8; 32]),
                    ObservedConsensusConfiguration::new(good_chain.clone(), good_genesis, [0x01u8; 32], 4, 0),
                );
                assert_eq!(
                    AuthorizedProposalVoteSnapshot::try_bind(owner, Arc::new(pv.clone()))
                        .expect_err("commitment mismatch"),
                    SnapshotCoherenceError::AuthorityCommitmentMismatch
                );

                // Wrong chain identity only.
                let owner = CurrentAuthorizationOwner::establish_for_fixture(
                    build("qbind-runtime-chain-0xdeadbeefdeadbeef".to_string(), good_genesis, good_commit),
                    ObservedConsensusConfiguration::new(
                        "qbind-runtime-chain-0xdeadbeefdeadbeef".to_string(),
                        good_genesis,
                        good_commit,
                        4,
                        0,
                    ),
                );
                assert_eq!(
                    AuthorizedProposalVoteSnapshot::try_bind(owner, Arc::new(pv.clone()))
                        .expect_err("chain mismatch"),
                    SnapshotCoherenceError::ChainIdentityMismatch
                );
            }

            // ================================================================
            // Run 422 D7-A2 (finding #2, corrective) — bind the COMPLETE
            // selected v2 domain: `expected_wire_chain_id`.
            //
            // Before this correction `try_bind` checked genesis, commitment,
            // membership, key provider and the runtime-chain label, but NOT the
            // domain's `expected_wire_chain_id`. An owner authorized for domain
            // A could therefore admit a verifier B whose domain differed ONLY in
            // `expected_wire_chain_id` (runtime chain, genesis and commitment
            // unchanged; membership and key provider objects shared). These
            // tests demonstrate the closed gap plus real ML-DSA-44 acceptance
            // controls.
            // ================================================================

            /// A v2 domain identical to [`d5_control_domain`] in runtime chain
            /// id, genesis identity and authority commitment, differing ONLY in
            /// `expected_wire_chain_id`. Trusted, test-identified fixture data.
            fn wire_variant_domain(expected_wire_chain_id: u32) -> ProposalVoteSigningDomainV2 {
                let base = d5_control_domain();
                ProposalVoteSigningDomainV2::try_new(
                    base.runtime_chain_id(),
                    expected_wire_chain_id,
                    *base.genesis_identity(),
                    *base.authority_commitment(),
                )
                .expect("valid wire-variant domain")
            }

            /// A `BlockProposal` at height 1 carrying wire `chain_id = wire`,
            /// signed by `proposer` over `domain`'s v2 preimage.
            fn signed_proposal_v2_wire(
                proposer: u16,
                wire: u32,
                fixture: &Fixture,
                domain: &ProposalVoteSigningDomainV2,
            ) -> BlockProposal {
                let mut header = base_header(proposer);
                header.chain_id = wire;
                let mut p = BlockProposal {
                    header,
                    qc: None,
                    txs: vec![],
                    signature: vec![],
                };
                let preimage = domain.proposal_preimage(&p);
                let sk = fixture.sks.get(&ValidatorId(proposer as u64)).expect("sk");
                p.signature = MlDsa44Backend::sign(sk, &preimage).expect("sign");
                p
            }

            /// A `Vote` at height 1 carrying wire `chain_id = wire`, signed by
            /// `voter` over `domain`'s v2 preimage.
            fn signed_vote_v2_wire(
                voter: u16,
                wire: u32,
                fixture: &Fixture,
                domain: &ProposalVoteSigningDomainV2,
            ) -> Vote {
                let mut v = base_vote(voter);
                v.chain_id = wire;
                let preimage = domain.vote_preimage(&v);
                let sk = fixture.sks.get(&ValidatorId(voter as u64)).expect("sk");
                v.signature = MlDsa44Backend::sign(sk, &preimage).expect("sign");
                v
            }

            // -------- Owner A paired with verifier B that differs ONLY in
            // `expected_wire_chain_id` ⇒ cannot bind (WireChainIdMismatch);
            // coherent A and coherent B each bind to their own verifier. ------
            #[test]
            fn d7a2_bind_rejects_owner_a_verifier_b_differ_only_in_wire_chain_id() {
                let f = make_fixture(4);
                let domain_a = d5_control_domain(); // expected wire 0
                let domain_b = wire_variant_domain(1); // ONLY wire differs (→ 1)

                // Precondition: the two domains are identical EXCEPT the wire id.
                assert_eq!(domain_a.runtime_chain_id(), domain_b.runtime_chain_id());
                assert_eq!(domain_a.genesis_identity(), domain_b.genesis_identity());
                assert_eq!(
                    domain_a.authority_commitment(),
                    domain_b.authority_commitment()
                );
                assert_ne!(
                    domain_a.expected_wire_chain_id(),
                    domain_b.expected_wire_chain_id()
                );

                // Verifier B shares the SAME fixture membership + key provider as
                // A (make_ctx_v2 clones the shared `Arc`s from `f`).
                let pv_b = make_ctx_v2(&f, None, domain_b.clone());

                // Owner authorized for the COMPLETE domain A: it shares B's
                // actual membership and key-provider objects and the same
                // genesis / commitment / runtime-chain identity (all unchanged
                // between A and B), but independently holds domain A's expected
                // wire chain id (0) — read from A, NOT copied from verifier B.
                let candidate = Arc::new(
                    GenesisConsensusAuthority::for_verification_snapshot_fixture(
                        snapshot_chain_identity_label(domain_b.runtime_chain_id()),
                        *domain_b.genesis_identity(),
                        *domain_b.authority_commitment(),
                        domain_a.expected_wire_chain_id(), // owner's own authorized wire id (A = 0)
                        pv_b.validators.clone(),           // share B's membership (ptr_eq holds)
                        pv_b.key_provider.clone(),         // share B's key provider (ptr_eq holds)
                    ),
                );
                let observed = candidate.config_identity();
                let owner = CurrentAuthorizationOwner::establish_for_fixture(candidate, observed);

                // Every OTHER coherence field matches; ONLY the expected wire
                // chain id differs ⇒ the sole failure is WireChainIdMismatch.
                let err = AuthorizedProposalVoteSnapshot::try_bind(owner, Arc::new(pv_b.clone()))
                    .expect_err(
                        "owner authorized for domain A must not admit verifier B differing only \
                         in expected_wire_chain_id",
                    );
                assert_eq!(err, SnapshotCoherenceError::WireChainIdMismatch);

                // Controls: a coherently-authorized owner DOES bind to its own
                // verifier for BOTH A and B — so the rejection above is
                // attributable to the wire-chain binding, not to B (or A) being
                // an unbindable verifier.
                let pv_a = make_ctx_v2(&f, None, domain_a.clone());
                let _ = coherent_snapshot_for(&pv_a); // owner-A ⇔ verifier-A binds
                let _ = coherent_snapshot_for(&pv_b); // owner-B ⇔ verifier-B binds
            }

            // -------- Proposal: real ML-DSA-44 controls. A B-domain proposal is
            // valid under coherently-authorized B, while A cannot authorize it;
            // the matching-A positive control is retained. -------------------
            #[test]
            fn d7a2_wire_domain_proposal_ml_dsa_controls() {
                let f = make_fixture(4);
                let domain_a = d5_control_domain(); // wire 0
                let domain_b = wire_variant_domain(1); // wire 1, else identical
                let pv_a = make_ctx_v2(&f, None, domain_a.clone());
                let pv_b = make_ctx_v2(&f, None, domain_b.clone());

                // A B-domain proposal carries B's wire id (1) and is signed over
                // B's preimage by validator 1 (leader for view 1).
                let p_b = signed_proposal_v2_wire(1, 1, &f, &domain_b);

                // Direct ML-DSA-44 control: valid under domain B, rejected under
                // domain A (same keys/membership — so the divergence is purely
                // the domain, including its expected wire chain id).
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p_b,
                        ValidatorId(1),
                        f.validators.as_ref(),
                        f.kp.as_ref(),
                        f.br.as_ref(),
                        &domain_b,
                    )
                    .is_ok(),
                    "B-domain proposal is valid under B"
                );
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p_b,
                        ValidatorId(1),
                        f.validators.as_ref(),
                        f.kp.as_ref(),
                        f.br.as_ref(),
                        &domain_a,
                    )
                    .is_err(),
                    "A cannot authorize the B-domain proposal"
                );

                // Real handler: valid under coherently-authorized B (accepted).
                {
                    let current_b = coherent_snapshot_for(&pv_b);
                    let gate = pv_binding_gate(4);
                    let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    let mut restore = RestoreCatchupModeState::from_config(None);
                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv_b),
                        Some(&current_b),
                        &p_b,
                        &metrics,
                        None,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(
                        stats.inbound_proposal_verify_accepted, 1,
                        "B-domain proposal accepted under coherently-authorized B"
                    );
                    assert_eq!(stats.inbound_proposal_verify_rejected_total, 0);
                }

                // Real handler: A cannot authorize the B-domain proposal — the
                // admitted-A verifier rejects it (wire chain mismatch) before
                // any delivery/effect.
                {
                    let current_a = coherent_snapshot_for(&pv_a);
                    let gate = pv_binding_gate(4);
                    let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    let mut restore = RestoreCatchupModeState::from_config(None);
                    let facade = D7ActionRecorder::default();
                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv_a),
                        Some(&current_a),
                        &p_b,
                        &metrics,
                        Some(&facade),
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(stats.inbound_proposal_verify_accepted, 0);
                    assert_eq!(stats.inbound_proposal_verify_rejected_total, 1);
                    assert_eq!(stats.inbound_proposal_rejected_wire_chain_mismatch, 1);
                    assert_eq!(stats.inbound_proposals_delivered, 0);
                    assert_eq!(facade.total(), 0);
                }

                // Retained matching-A positive control: an A-domain proposal
                // (wire 0) is accepted under coherently-authorized A.
                {
                    let current_a = coherent_snapshot_for(&pv_a);
                    let p_a = signed_proposal_v2_wire(1, 0, &f, &domain_a);
                    let gate = pv_binding_gate(4);
                    let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    let mut restore = RestoreCatchupModeState::from_config(None);
                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv_a),
                        Some(&current_a),
                        &p_a,
                        &metrics,
                        None,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(
                        stats.inbound_proposal_verify_accepted, 1,
                        "matching-A proposal accepted under coherently-authorized A"
                    );
                    assert_eq!(stats.inbound_proposal_verify_rejected_total, 0);
                }
            }

            // -------- Vote: real ML-DSA-44 controls. A B-domain vote is valid
            // under coherently-authorized B, while A cannot authorize it; the
            // matching-A positive control is retained. -----------------------
            #[test]
            fn d7a2_wire_domain_vote_ml_dsa_controls() {
                let f = make_fixture(4);
                let domain_a = d5_control_domain(); // wire 0
                let domain_b = wire_variant_domain(1); // wire 1, else identical
                let pv_a = make_ctx_v2(&f, None, domain_a.clone());
                let pv_b = make_ctx_v2(&f, None, domain_b.clone());

                let v_b = signed_vote_v2_wire(1, 1, &f, &domain_b);

                // Direct ML-DSA-44 control: valid under B, rejected under A.
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &v_b,
                        ValidatorId(1),
                        f.validators.as_ref(),
                        f.kp.as_ref(),
                        f.br.as_ref(),
                        &domain_b,
                    )
                    .is_ok(),
                    "B-domain vote is valid under B"
                );
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &v_b,
                        ValidatorId(1),
                        f.validators.as_ref(),
                        f.kp.as_ref(),
                        f.br.as_ref(),
                        &domain_a,
                    )
                    .is_err(),
                    "A cannot authorize the B-domain vote"
                );

                // Real handler: accepted under coherently-authorized B.
                {
                    let current_b = coherent_snapshot_for(&pv_b);
                    let gate = pv_binding_gate(4);
                    let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    deliver_vote_fresh(
                        &mut engine,
                        &mut stats,
                        None,
                        Some(&pv_b),
                        Some(&current_b),
                        &v_b,
                        &metrics,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(
                        stats.inbound_vote_verify_accepted, 1,
                        "B-domain vote accepted under coherently-authorized B"
                    );
                    assert_eq!(stats.inbound_vote_verify_rejected_total, 0);
                }

                // Real handler: A cannot authorize the B-domain vote.
                {
                    let current_a = coherent_snapshot_for(&pv_a);
                    let gate = pv_binding_gate(4);
                    let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    deliver_vote_fresh(
                        &mut engine,
                        &mut stats,
                        None,
                        Some(&pv_a),
                        Some(&current_a),
                        &v_b,
                        &metrics,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(stats.inbound_vote_verify_accepted, 0);
                    assert_eq!(stats.inbound_vote_verify_rejected_total, 1);
                    assert_eq!(stats.inbound_vote_rejected_wire_chain_mismatch, 1);
                    assert_eq!(stats.inbound_votes_delivered, 0);
                }

                // Retained matching-A positive control.
                {
                    let current_a = coherent_snapshot_for(&pv_a);
                    let v_a = signed_vote_v2_wire(1, 0, &f, &domain_a);
                    let gate = pv_binding_gate(4);
                    let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    deliver_vote_fresh(
                        &mut engine,
                        &mut stats,
                        None,
                        Some(&pv_a),
                        Some(&current_a),
                        &v_a,
                        &metrics,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(
                        stats.inbound_vote_verify_accepted, 1,
                        "matching-A vote accepted under coherently-authorized A"
                    );
                    assert_eq!(stats.inbound_vote_verify_rejected_total, 0);
                }
            }

            // ================================================================
            // Run 422 D7-A2 (finding #2, corrective — section 3): the IMMEDIATE
            // inbound Proposal → engine → outbound handoff signs the
            // engine-produced action with the BOUND authority (the admitted A),
            // never the separately-supplied `pv_authority` (B) or the
            // Timeout/NewView signer.
            //
            // This drives the REAL `handle_inbound_consensus_msg` handler with a
            // coherent snapshot A (whose bound verifier carries A's local
            // signer), a separately-supplied authority B (with its OWN
            // instrumented local signer), a recording facade, and directly
            // instrumented signers. The inbound A-proposal from the view leader
            // makes the local engine emit a `BroadcastVote`, so the handoff at
            // `forward_actions_to_facade` is actually reached (positive
            // control). B's signer must never be invoked, and the emitted vote
            // must be signed by A and verify under A's domain.
            // ================================================================
            #[test]
            fn d7a2_immediate_handoff_uses_bound_authority_not_supplied_b() {
                use std::sync::atomic::{AtomicU64, Ordering::SeqCst};
                use std::sync::Mutex;

                // Instrumented signer: records each invocation, then delegates.
                struct InstrumentedSigner {
                    inner: LocalKeySigner,
                    vote_calls: Arc<AtomicU64>,
                    proposal_calls: Arc<AtomicU64>,
                    timeout_calls: Arc<AtomicU64>,
                }
                impl ValidatorSigner for InstrumentedSigner {
                    fn validator_id(&self) -> &ValidatorId {
                        self.inner.validator_id()
                    }
                    fn suite_id(&self) -> u16 {
                        self.inner.suite_id()
                    }
                    fn sign_proposal(
                        &self,
                        p: &[u8],
                    ) -> Result<Vec<u8>, crate::validator_signer::SignError> {
                        self.proposal_calls.fetch_add(1, SeqCst);
                        self.inner.sign_proposal(p)
                    }
                    fn sign_vote(
                        &self,
                        p: &[u8],
                    ) -> Result<Vec<u8>, crate::validator_signer::SignError> {
                        self.vote_calls.fetch_add(1, SeqCst);
                        self.inner.sign_vote(p)
                    }
                    fn sign_timeout(
                        &self,
                        view: u64,
                        high_qc: Option<&qbind_consensus::qc::QuorumCertificate<[u8; 32]>>,
                    ) -> Result<Vec<u8>, crate::validator_signer::SignError> {
                        self.timeout_calls.fetch_add(1, SeqCst);
                        self.inner.sign_timeout(view, high_qc)
                    }
                    fn sign_timeout_with_chain_id(
                        &self,
                        chain_id: ChainId,
                        view: u64,
                        high_qc: Option<&qbind_consensus::qc::QuorumCertificate<[u8; 32]>>,
                    ) -> Result<Vec<u8>, crate::validator_signer::SignError> {
                        self.timeout_calls.fetch_add(1, SeqCst);
                        self.inner.sign_timeout_with_chain_id(chain_id, view, high_qc)
                    }
                }

                // Facade recording every emitted vote.
                #[derive(Default)]
                struct HandoffFacade {
                    broadcast_votes: Mutex<Vec<Vote>>,
                    other: AtomicU64,
                }
                impl ConsensusNetworkFacade for HandoffFacade {
                    fn send_vote_to(
                        &self,
                        _to: ValidatorId,
                        v: &Vote,
                    ) -> Result<(), qbind_consensus::network::NetworkError> {
                        self.broadcast_votes.lock().unwrap().push(v.clone());
                        Ok(())
                    }
                    fn broadcast_vote(
                        &self,
                        v: &Vote,
                    ) -> Result<(), qbind_consensus::network::NetworkError> {
                        self.broadcast_votes.lock().unwrap().push(v.clone());
                        Ok(())
                    }
                    fn broadcast_proposal(
                        &self,
                        _p: &BlockProposal,
                    ) -> Result<(), qbind_consensus::network::NetworkError> {
                        self.other.fetch_add(1, SeqCst);
                        Ok(())
                    }
                    fn broadcast_consensus_msg(
                        &self,
                        _m: &ConsensusNetMsg,
                    ) -> Result<(), qbind_consensus::network::NetworkError> {
                        self.other.fetch_add(1, SeqCst);
                        Ok(())
                    }
                }

                let f = make_fixture(4);
                // Domain A expects wire chain id 1, matching the wire chain id
                // the engine stamps on the self-vote it produces from an
                // inbound proposal (so the outbound vote is actually signed and
                // emitted rather than suppressed for a wire mismatch).
                let domain_a = wire_variant_domain(1);
                let domain_b = alt_domain_b();

                let a_votes = Arc::new(AtomicU64::new(0));
                let a_proposals = Arc::new(AtomicU64::new(0));
                let a_timeouts = Arc::new(AtomicU64::new(0));
                let b_votes = Arc::new(AtomicU64::new(0));
                let b_proposals = Arc::new(AtomicU64::new(0));
                let b_timeouts = Arc::new(AtomicU64::new(0));

                let build_pv = |domain: ProposalVoteSigningDomainV2,
                                vote_calls: Arc<AtomicU64>,
                                proposal_calls: Arc<AtomicU64>,
                                timeout_calls: Arc<AtomicU64>|
                 -> ProposalVoteAuthority {
                    let sk = f.sk_objs.get(&ValidatorId(0)).expect("sk").clone();
                    let inner = LocalKeySigner::new(ValidatorId(0), TEST_SUITE_U16, sk);
                    let signer: Arc<dyn ValidatorSigner> = Arc::new(InstrumentedSigner {
                        inner,
                        vote_calls,
                        proposal_calls,
                        timeout_calls,
                    });
                    ProposalVoteAuthority {
                        validators: f.validators.clone(),
                        key_provider: f.kp.clone(),
                        backend_registry: f.br.clone(),
                        chain_id: QBIND_DEVNET_CHAIN_ID,
                        signer: Some(signer),
                        signing_domain: domain,
                    }
                };

                // Bound verifier A (its local signer is the ONLY one that may
                // sign the outbound vote) and separately-supplied authority B.
                let pv_a = build_pv(
                    domain_a.clone(),
                    a_votes.clone(),
                    a_proposals.clone(),
                    a_timeouts.clone(),
                );
                let pv_b = build_pv(
                    domain_b.clone(),
                    b_votes.clone(),
                    b_proposals.clone(),
                    b_timeouts.clone(),
                );
                let current_a = coherent_snapshot_for(&pv_a);

                // Inbound A-proposal from the view-1 leader (validator 1), wire
                // chain id 1 so it verifies under domain A. The local engine
                // (validator 0) accepts it and emits a self-vote → the immediate
                // handoff is reached.
                let p_a = signed_proposal_v2_wire(1, 1, &f, &domain_a);
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);
                let facade = HandoffFacade::default();

                // Run 422 D7-D10 Correction A: the self-Vote the engine emits
                // from this inbound Proposal is signer-eligible under the bound
                // A authority, so the immediate handoff now requires a journal.
                let journal = fresh_signing_journal();
                deliver_proposal_fresh_j(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    None,
                    Some(&pv_b), // separately-supplied authority is B ...
                    Some(&current_a), // ... but the admitted snapshot is A
                    &p_a,
                    &metrics,
                    Some(&facade),
                    Some(&origin),
                    Some(&gate),
                    Some(&journal),
                    ConsensusVerificationPolicy::Required,
                );

                // Positive control: the action path was actually reached — the
                // proposal verified under A, the engine accepted it and emitted
                // an outbound vote.
                assert_eq!(stats.inbound_proposal_verify_accepted, 1, "verified under A");
                assert_eq!(
                    stats.inbound_proposals_engine_accepted, 1,
                    "engine accepted and produced an action (handoff reached)"
                );
                assert_eq!(stats.outbound_votes_sent, 1, "outbound vote emitted");

                // The bound authority A signed the outbound vote; B's signer and
                // the Timeout signer were NEVER invoked.
                assert_eq!(a_votes.load(SeqCst), 1, "A signed the emitted vote");
                assert_eq!(b_votes.load(SeqCst), 0, "B's signer never invoked");
                assert_eq!(b_proposals.load(SeqCst), 0);
                assert_eq!(b_timeouts.load(SeqCst), 0);
                assert_eq!(a_timeouts.load(SeqCst), 0, "no Timeout-signer fallback");

                // Exactly one vote reached the facade, and it verifies under A's
                // selected domain (the domain emission is supported for).
                let emitted = facade.broadcast_votes.lock().unwrap();
                assert_eq!(emitted.len(), 1, "one vote emitted to the facade");
                assert_eq!(facade.other.load(SeqCst), 0);
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &emitted[0],
                        ValidatorId(0),
                        f.validators.as_ref(),
                        f.kp.as_ref(),
                        f.br.as_ref(),
                        &domain_a,
                    )
                    .is_ok(),
                    "emitted vote verifies under the bound A domain"
                );
                // It must NOT verify under B's foreign domain (attributes the
                // emission to A, not B).
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &emitted[0],
                        ValidatorId(0),
                        f.validators.as_ref(),
                        f.kp.as_ref(),
                        f.br.as_ref(),
                        &domain_b,
                    )
                    .is_err(),
                    "emitted vote does NOT verify under supplied B"
                );
            }

            // -------- Proposal: the handler consumes the ADMITTED snapshot's
            // verifier and IGNORES a separately-supplied `pv_authority`. ------
            #[test]
            fn d7a2_proposal_admitted_verifier_ignores_supplied_pv() {
                let fa = make_fixture(4);
                let fb = make_fixture(4); // same count/domain, DIFFERENT keys
                let pv_a = make_ctx(&fa, None);
                let pv_b = make_ctx(&fb, None);
                let current = snapshot_matching(&pv_a); // admitted snapshot bound to A

                // (i) An A-signed proposal is ACCEPTED even though the supplied
                // context is B — proving the admitted A verifier was used and B
                // was ignored. Independently, the A-signed message is INVALID
                // under B (different keys), so acceptance is attributable to the
                // admitted binding, not to B.
                let p_a = signed_proposal(1, &fa);
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p_a,
                        ValidatorId(1),
                        fb.validators.as_ref(),
                        fb.kp.as_ref(),
                        fb.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_err(),
                    "the A-signed proposal must NOT verify under B"
                );
                {
                    let gate = pv_binding_gate(4);
                    let origin =
                        AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    let mut restore = RestoreCatchupModeState::from_config(None);
                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv_b), // supplied context is B ...
                        Some(&current), // ... but the admitted snapshot is A
                        &p_a,
                        &metrics,
                        None,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(
                        stats.inbound_proposal_verify_accepted, 1,
                        "handler used the admitted A verifier, ignoring supplied B"
                    );
                    assert_eq!(stats.inbound_proposal_verify_rejected_total, 0);
                }

                // (ii) A B-signed proposal (valid under B) is REJECTED, because
                // the handler verifies under the admitted A — even though B was
                // supplied. The negative is attributable to the binding.
                let p_b = signed_proposal(1, &fb);
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p_b,
                        ValidatorId(1),
                        fb.validators.as_ref(),
                        fb.kp.as_ref(),
                        fb.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_ok(),
                    "control: the B-signed proposal is valid under B"
                );
                {
                    let gate = pv_binding_gate(4);
                    let origin =
                        AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    let mut restore = RestoreCatchupModeState::from_config(None);
                    let facade = D7ActionRecorder::default();
                    deliver_proposal_fresh(
                        &mut engine,
                        &mut stats,
                        &mut restore,
                        None,
                        Some(&pv_b),
                        Some(&current),
                        &p_b,
                        &metrics,
                        Some(&facade),
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(stats.inbound_proposal_verify_accepted, 0);
                    assert_eq!(stats.inbound_proposal_verify_rejected_total, 1);
                    assert_eq!(stats.inbound_proposals_delivered, 0);
                    assert_eq!(facade.total(), 0, "no outbound actions on rejection");
                }
            }

            // -------- Vote: the handler consumes the ADMITTED snapshot's
            // verifier and IGNORES a separately-supplied `pv_authority`. ------
            #[test]
            fn d7a2_vote_admitted_verifier_ignores_supplied_pv() {
                let fa = make_fixture(4);
                let fb = make_fixture(4);
                let pv_a = make_ctx(&fa, None);
                let pv_b = make_ctx(&fb, None);
                let current = snapshot_matching(&pv_a);

                // (i) A-signed vote accepted (admitted A used, supplied B ignored).
                let v_a = signed_vote(1, &fa);
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &v_a,
                        ValidatorId(1),
                        fb.validators.as_ref(),
                        fb.kp.as_ref(),
                        fb.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_err(),
                    "the A-signed vote must NOT verify under B"
                );
                {
                    let gate = pv_binding_gate(4);
                    let origin =
                        AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    deliver_vote_fresh(
                        &mut engine,
                        &mut stats,
                        None,
                        Some(&pv_b),
                        Some(&current),
                        &v_a,
                        &metrics,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(
                        stats.inbound_vote_verify_accepted, 1,
                        "handler used the admitted A verifier, ignoring supplied B"
                    );
                    assert_eq!(stats.inbound_vote_verify_rejected_total, 0);
                }

                // (ii) B-signed vote (valid under B) rejected under admitted A.
                let v_b = signed_vote(1, &fb);
                assert!(
                    qbind_consensus::verify_vote_msg_with_domain(
                        &v_b,
                        ValidatorId(1),
                        fb.validators.as_ref(),
                        fb.kp.as_ref(),
                        fb.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_ok(),
                    "control: the B-signed vote is valid under B"
                );
                {
                    let gate = pv_binding_gate(4);
                    let origin =
                        AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                    let mut engine = make_engine(ValidatorId(0), 4);
                    let mut stats = BinaryConsensusLoopInboundStats::default();
                    let metrics = make_metrics();
                    deliver_vote_fresh(
                        &mut engine,
                        &mut stats,
                        None,
                        Some(&pv_b),
                        Some(&current),
                        &v_b,
                        &metrics,
                        Some(&origin),
                        Some(&gate),
                        ConsensusVerificationPolicy::Required,
                    );
                    assert_eq!(stats.inbound_vote_verify_accepted, 0);
                    assert_eq!(stats.inbound_vote_verify_rejected_total, 1);
                    assert_eq!(stats.inbound_votes_delivered, 0);
                }
            }

            // -------- Proposal: a correctly re-signed message carrying an
            // UNAUTHORIZED epoch is rejected BEFORE crypto and any effect. ----
            #[test]
            fn d7a2_proposal_unauthorized_epoch_rejected_before_effects() {
                let fixture = make_fixture(4);
                let backend_calls = Arc::new(AtomicU64::new(0));
                let pv = counting_pv(&fixture, &backend_calls);
                let current = snapshot_matching(&pv); // authorizes founding epoch 0
                let gate = pv_binding_gate(4);
                let origin = AuthenticatedConsensusOrigin::new(pv_node_for(1), ValidatorId(1));
                let mut engine = make_engine(ValidatorId(0), 4);
                let view_before = engine.current_view();
                let mut stats = BinaryConsensusLoopInboundStats::default();
                let metrics = make_metrics();
                let mut restore = RestoreCatchupModeState::from_config(None);
                let facade = D7ActionRecorder::default();

                // Build a proposal at epoch 1, correctly signed under the same
                // D6 domain (so the SIGNATURE is valid; only the epoch is
                // unauthorized).
                let mut header = base_header(1);
                header.epoch = 1;
                let mut p = BlockProposal {
                    header,
                    qc: None,
                    txs: vec![],
                    signature: vec![],
                };
                let preimage = d5_control_domain().proposal_preimage(&p);
                let sk = fixture.sks.get(&ValidatorId(1)).expect("sk");
                p.signature = MlDsa44Backend::sign(sk, &preimage).expect("sign");
                assert!(
                    qbind_consensus::verify_proposal_msg_with_domain(
                        &p,
                        ValidatorId(1),
                        fixture.validators.as_ref(),
                        fixture.kp.as_ref(),
                        fixture.br.as_ref(),
                        &d5_control_domain(),
                    )
                    .is_ok(),
                    "control: the epoch-1 proposal signature is valid"
                );
                backend_calls.store(0, SeqCst);

                let detector = deliver_proposal_fresh(
                    &mut engine,
                    &mut stats,
                    &mut restore,
                    None,
                    Some(&pv),
                    Some(&current),
                    &p,
                    &metrics,
                    Some(&facade),
                    Some(&origin),
                    Some(&gate),
                    ConsensusVerificationPolicy::Required,
                );

                assert_eq!(gate.metrics().accepted(), 1, "F6 admitted first");
                // Rejected for unauthorized epoch, BEFORE crypto and any effect.
                assert_eq!(stats.inbound_proposal_epoch_unauthorized_total, 1);
                assert_eq!(
                    backend_calls.load(SeqCst),
                    0,
                    "epoch check precedes crypto: backend not called"
                );
                assert_eq!(stats.proposal_vote_crypto_verify_latency_observations_total, 0);
                assert_eq!(stats.inbound_proposal_verify_accepted, 0);
                assert_eq!(stats.inbound_proposals_delivered, 0);
                assert_eq!(stats.inbound_proposals_engine_accepted, 0);
                assert_eq!(facade.total(), 0, "no outbound actions on rejection");
                assert!(detector.header_cache.is_empty());
                assert_eq!(engine.current_view(), view_before);
            }

            // -------- Vote: a correctly re-signed message carrying an
            // UNAUTHORIZED epoch is rejected BEFORE crypto and any effect. ----
